      continue;
    }
    const reps = newItems.map((n, k) => [n, k]).filter(([n, k]) => !used.has(k) && n.replaces && norm(n.replaces) === norm(o.code));
    if (reps.length) { for (const [n, k] of reps) { used.add(k); changes.push({ type: 'replaced', old: o, item: n }); } continue; }
    const why = reasons[norm(o.code) + '|' + Number(o.dz)] || reasons[norm(o.code) + '|0'] || 'removed';
    changes.push({ type: why, old: o });
  }
  newItems.forEach((n, k) => { if (!used.has(k)) changes.push({ type: 'added', item: n }); });
  return changes;
}
function changeOrder(o, edit) {
  const items = cleanItems(edit.items);
  if (!items) return { error: 'Some item lines are not valid (packets must be whole numbers above 0).' };
  if (!items.length) return { error: 'The order has no items left. Add at least one item.' };
  const oldItems = itemsOf(o);
  const changes = diff(oldItems, items, edit.removed);
  let ship = shipOf(o);
  if (edit.shipping !== undefined && edit.shipping !== null && edit.shipping !== '') {
    const s = Number(edit.shipping);
    if (!(s >= 0 && s < 1000000)) return { error: 'Shipping must be a number in ₹ (0 for free shipping).' };
    ship = r2(s);
  }
  const handling = Number(o.handling) || 0;
  const tot = totals(items, handling);
  const note = clip(edit.note, 500);
  const lang = langOf(o);
  const stored = items.map((x) => { const y = Object.assign({}, x); delete y.stock; delete y.replaces; return y; });
  const enLines = changes.map((c) => changeLine(L.en, c));
  return { items: stored, changes, enLines, ship, handling, tot, note, lang, itemsChanged: changes.length > 0, shipChanged: ship !== shipOf(o) };
}

// ---- session ----
const tokenHash = b.token ? sha256('session:' + String(b.token)) : '';
const session = tokenHash ? sessions.find((s) => s.kind === 'session' && s.hash === tokenHash && Number(s.exp_ms) > nowMs) : null;
const PUBLIC = ['ping', 'request_code', 'verify_code'];

if (!PUBLIC.includes(action) && !session) {
  fail('login', 'Please log in again.');
} else if (action === 'ping') {
  reply({ crypto: cryptoMode, time: now });
} else if (action === 'request_code') {
  const codes = sessions.filter((s) => s.kind === 'otp');
  const lastMs = Math.max(0, ...codes.map((s) => Number(s.created_ms) || 0));
  const lastHour = codes.filter((s) => nowMs - (Number(s.created_ms) || 0) < 3600 * 1000).length;
  if (nowMs - lastMs < 60 * 1000) fail('wait', 'A code was sent less than a minute ago. Please check WhatsApp, or wait a minute and try again.');
  else if (lastHour >= CODES_PER_HOUR) fail('wait', 'Too many codes in the last hour. Please try again later.');
  else if (!mahekWindowOpen()) fail('window', 'WhatsApp only lets the bot message you within 24 hours of your last message to it. Send "hi" to the bot on WhatsApp (+91 93227 02543), then tap "Send code" again.');
  else {
    const code = randomCode(), key = 'otp-' + randomHex(8);
    out.rows.push({ key, kind: 'otp', hash: sha256(key + ':' + code), exp_ms: nowMs + CODE_MIN * 60 * 1000, tries: 0, created_ms: nowMs });
    out.cleanup = true;
    out.messages.push({ to: MAHEK, kind: 'code', payload: { messaging_product: 'whatsapp', recipient_type: 'individual', to: MAHEK, type: 'text', text: { preview_url: false, body: '🔐 Your Raj Creation orders login code is *' + code + '*\n\nIt works for ' + CODE_MIN + ' minutes. Never share it with anyone – Raj Creation will never ask you for it.' } } });
    reply({ sent: true, to: '+91 •••••' + MAHEK.slice(-5), minutes: CODE_MIN });
  }
} else if (action === 'verify_code') {
  const code = String(b.code || '').replace(/\D/g, '');
  const otp = sessions.filter((s) => s.kind === 'otp' && Number(s.exp_ms) > nowMs).sort((x, y) => (Number(y.created_ms) || 0) - (Number(x.created_ms) || 0))[0];
  if (!otp) fail('expired', 'This code has expired or was already used. Tap "Send code" to get a new one.');
  else if (code.length === 6 && sha256(otp.key + ':' + code) === otp.hash) {
    const token = randomHex(32);
    out.rows.push({ key: otp.key, kind: 'otp', hash: otp.hash, exp_ms: 0, tries: Number(otp.tries) || 0, created_ms: Number(otp.created_ms) || 0 });
    out.rows.push({ key: 'ses-' + randomHex(8), kind: 'session', hash: sha256('session:' + token), exp_ms: nowMs + SESSION_DAYS * 864e5, tries: 0, created_ms: nowMs });
    reply({ token, exp_ms: nowMs + SESSION_DAYS * 864e5 });
  } else {
    const tries = (Number(otp.tries) || 0) + 1;
    const left = CODE_TRIES - tries;
    out.rows.push({ key: otp.key, kind: 'otp', hash: otp.hash, exp_ms: left > 0 ? Number(otp.exp_ms) : 0, tries, created_ms: Number(otp.created_ms) || 0 });
    fail('code', left > 0 ? 'Wrong code. ' + left + (left === 1 ? ' try' : ' tries') + ' left.' : 'Wrong code too many times. Tap "Send code" to get a new one.');
  }
} else if (action === 'logout') {
  out.rows.push({ key: session.key, kind: 'session', hash: session.hash, exp_ms: 0, tries: 0, created_ms: Number(session.created_ms) || 0 });
  reply({});
} else if (action === 'list') {
  const orders = recent.slice().sort((x, y) => (Number(y.created_ms) || 0) - (Number(x.created_ms) || 0)).map((o) => ({
    order_id: o.order_id, name: o.name || '', shop: o.shop || '', city: o.city || '', phone: o.phone || '', status: o.status || 'new', level: o.level || '',
    total: Number(o.total) || 0, grand_total: Number(o.grand_total) || 0, shipping: shipOf(o), packets: Number(o.packets) || 0, lines: itemsOf(o).length,
    created_at: o.created_at || '', updated_at: o.updated_at || '', confirmed_at: o.confirmed_at || '', version: Number(o.version) || 1, needs_sales: o.needs_sales ? 1 : 0,
  }));
  reply({ orders, session_exp_ms: Number(session.exp_ms) });
} else if (!thisOrder) {
  fail('missing', 'Order ' + clip(b.order_id, 30) + ' was not found.');
} else if (action === 'get') {
  reply({ order: orderOut(thisOrder), customer: { name: (customer && customer.whatsapp_name) || '', last_in_at: (customer && customer.last_in_at) || '', window_open: windowOpen(customer), paused: !!(customer && parseT(customer.paused_until) && parseT(customer.paused_until) > nowDt) }, template_ok: !!(tpl.update && tpl.update.status === 'APPROVED') });
} else if (['preview', 'save'].includes(action)) {
  const o = thisOrder;
  const ch = changeOrder(o, b);
  const confirm = !!b.confirm;
  const notify = !!b.notify && ch.itemsChanged;
  const open = windowOpen(customer);
  const tname = tpl.update && tpl.update.status === 'APPROVED' ? tpl.update.name : '';
  const how = !notify ? 'none' : open ? 'message' : tname ? 'template' : 'manual';
  if (ch.error) fail('invalid', ch.error);
  else if (Number(b.version) !== (Number(o.version) || 1)) fail('changed', 'This order was changed (by the customer or in WhatsApp) after you opened it. It has been reloaded – please make your changes again.', { order: orderOut(o) });
  else if (confirm && ch.ship < 0) fail('invalid', 'Please enter the shipping cost (0 for free shipping) before confirming.');
  else if (!confirm && !ch.itemsChanged && !ch.shipChanged) fail('nothing', 'Nothing was changed.');
  else {
    const text = notify ? customerMessage(o, ch.changes, ch.tot, ch.ship, ch.note, ch.lang) : '';
    const textEn = notify ? customerMessage(o, ch.changes, ch.tot, ch.ship, ch.note, 'en') : '';
    const grand = ch.ship >= 0 ? r2(ch.tot.total + ch.ship) : 0;
    if (action === 'preview') {
      reply({ how, message: text, message_en: ch.lang === 'en' ? '' : textEn, changes: ch.enLines, totals: Object.assign({}, ch.tot, { handling: ch.handling, shipping: ch.ship, grand_total: grand }), window_open: open });
    } else {
      const stamp = 'Changed by Mahek on the website ' + now + ': ' + (ch.enLines.join('; ') || (ch.shipChanged ? 'shipping ' + inr2(ch.ship) : 'confirmed'));
      const upd = Object.assign({}, o, {
        items: JSON.stringify(ch.items), lines_text: ch.items.map(lineFull).join('\n'), packets: ch.tot.packets, dozens: ch.tot.dozens,
        items_total: ch.tot.items_total, handling: ch.handling, gst: ch.tot.gst, total: ch.tot.total, shipping: ch.ship, grand_total: grand,
        updated_at: now, version: (Number(o.version) || 1) + (ch.itemsChanged ? 1 : 0),
        note: clip((ch.itemsChanged || ch.shipChanged ? stamp + (o.note ? ' | ' + o.note : '') : o.note || ''), 2000),
      });
      if (confirm) Object.assign(upd, { status: 'confirmed', confirmed_at: now, confirm_count: (Number(o.confirm_count) || 0) + 1 });
      delete upd.id; delete upd.createdAt; delete upd.updatedAt;
      out.order_update = upd;
      if (how === 'message') out.messages.push({ to: o.phone, kind: 'update', payload: { messaging_product: 'whatsapp', recipient_type: 'individual', to: o.phone, type: 'text', text: { preview_url: false, body: text.slice(0, 4096) } } });
      else if (how === 'template') {
        const p = (s, n) => clip(String(s).replace(/[\n\t]+/g, ' ').replace(/ {4,}/g, '   '), n);
        out.messages.push({ to: o.phone, kind: 'update', payload: { messaging_product: 'whatsapp', recipient_type: 'individual', to: o.phone, type: 'template', template: { name: tname, language: { code: 'en_US' }, components: [{ type: 'body', parameters: [
          { type: 'text', text: p((customer && customer.whatsapp_name) || o.name || 'there', 60) },
          { type: 'text', text: p(o.order_id, 30) },
          { type: 'text', text: p(ch.enLines.join('; ') + (ch.note ? '. Note: ' + ch.note : ''), 700) },
          { type: 'text', text: p(inr2(ch.tot.total) + ' incl. GST' + (ch.ship > 0 ? ' + shipping ' + inr2(ch.ship) : ch.ship === 0 ? ', free shipping' : ''), 80) },
        ] }] } } });
      } else if (how === 'manual') out.manual = { url: 'https://wa.me/' + o.phone + '?text=' + encodeURIComponent(text), message: text };
      if (confirm) {
        out.confirm = { mode: 'confirm', order: upd, customer: { phone: o.phone, name: (customer && customer.whatsapp_name) || o.name || '', last_in_at: (customer && customer.last_in_at) || '', lang: ch.lang } };
      }
      reply({ how, message: text, manual: out.manual, order: orderOut(upd), confirmed: confirm });
    }
  }
} else {
  fail('action', 'Unknown action.');
}
return [{ json: out }];

// What the page gets back. Adds the WhatsApp send results to the answer from "Handle".
const h = $('Handle').first().json;
const res = Object.assign({}, h.response || { ok: false, error: 'server', message: 'No answer.' });
const msgs = h.messages || [];
if (msgs.length) {
  let sent = [];
  try { sent = $('Send WhatsApp').all().map((i) => i.json || {}); } catch (e) { sent = []; }
  const results = msgs.map((m, i) => {
    const r = sent[i] || {};
    const id = r.messages && r.messages[0] && r.messages[0].id;
    const er = r.error ? (r.error.error_data && r.error.error_data.details) || r.error.message || JSON.stringify(r.error) : 'no answer from WhatsApp';
    return { kind: m.kind, ok: !!id, error: id ? '' : String(er).slice(0, 300) };
  });
  const code = results.find((r) => r.kind === 'code');
  if (code && !code.ok) {
    Object.assign(res, { ok: false, error: 'send', message: 'Could not send the code on WhatsApp (' + code.error + '). Send "hi" to the bot on WhatsApp, then try again.' });
    delete res.sent; delete res.to;
  }
  const upd = results.find((r) => r.kind === 'update');
  if (upd) {
    res.sent = upd.ok;
    if (!upd.ok) {
      res.send_error = upd.error;
      const o = res.order || {};
      if (res.message && o.phone) res.manual = { url: 'https://wa.me/' + o.phone + '?text=' + encodeURIComponent(res.message), message: res.message };
    }
  }
}
return [{ json: res }];
